function dashboardCharts(){const t=totals(),paid=filterRows(state.data.financial).filter(x=>x.entry_type==='Despesa'&&x.status==='Pago'),fuel=paid.filter(x=>/combustível/i.test(x.category)).reduce((s,x)=>s+financialValue(x),0),maint=paid.filter(x=>/manutenção/i.test(x.category)).reduce((s,x)=>s+financialValue(x),0),other=Math.max(0,t.costs-fuel-maint),max=Math.max(1,t.revenue,t.costs,fuel,maint,other),row=(name,value,kind='')=>'<div class="bar-row"><b>'+name+'</b><div class="track"><div class="fill '+kind+'" style="width:'+Math.max(2,value/max*100)+'%"></div></div><strong>'+brl.format(value)+'</strong></div>';return '<div class="charts"><section class="panel"><div class="panel-head"><div><p class="kicker">Visualização</p><h2>Recebimentos e pagamentos</h2></div></div><div class="bar-chart">'+row('Recebido',t.revenue)+row('Pago',t.costs,'cost')+row('Saldo',Math.max(0,t.balance))+'</div></section><section class="panel"><div class="panel-head"><div><p class="kicker">Composição realizada</p><h2>Onde está o gasto pago</h2></div></div><div class="bar-chart">'+row('Combustível',fuel,'cost')+row('Manutenção',maint,'maint')+row('Outros',other)+'</div></section></div>'}
