const collections={vehicle:'trucks',driver:'drivers',client:'clients',trip:'trips',expense:'expenses',fuel:'fuel',maintenance:'maintenance',document:'documents',financial:'financial',inspection:'inspections',occurrence:'occurrences',rule:'rules',financialCategory:'financialCategories',costCenter:'costCenters',paymentMethod:'paymentMethods',helper:'helpers',telemetry:'telemetry',journey:'journeys',tire:'tires',fine:'fines',inventory:'inventory'};
