function readFileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file)})}
async function prepareUpload(file,maxSide=1600){if(!file)return null;if(file.size>12*1024*1024)throw Error('O arquivo pode ter até 12 MB.');if(!file.type.startsWith('image/')){if(file.size>3*1024*1024)throw Error('PDFs podem ter até 3 MB.');return{name:file.name,data:await readFileData(file)}}const source=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const value=new Image();value.onload=()=>resolve(value);value.onerror=()=>reject(Error('Imagem inválida ou corrompida.'));value.src=source});const scale=Math.min(1,maxSide/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return{name:file.name.replace(/\.[^.]+$/,'.webp'),data:canvas.toDataURL('image/webp',.82)}}finally{URL.revokeObjectURL(source)}}
const taxRaw=value=>String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
const cpfMask=value=>{const d=String(value||'').replace(/\D/g,'').slice(0,11);return d.replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2')};
const cnpjMask=value=>{const d=taxRaw(value).slice(0,14);if(d.length<=2)return d;if(d.length<=5)return d.slice(0,2)+'.'+d.slice(2);if(d.length<=8)return d.slice(0,2)+'.'+d.slice(2,5)+'.'+d.slice(5);if(d.length<=12)return d.slice(0,2)+'.'+d.slice(2,5)+'.'+d.slice(5,8)+'/'+d.slice(8);return d.slice(0,2)+'.'+d.slice(2,5)+'.'+d.slice(5,8)+'/'+d.slice(8,12)+'-'+d.slice(12)};
function validCpf(value){const d=String(value||'').replace(/\D/g,'');if(d.length!==11||/^(\d)\1{10}$/.test(d))return false;const digit=size=>{let sum=0;for(let i=0;i<size;i++)sum+=Number(d[i])*(size+1-i);const rest=(sum*10)%11;return rest===10?0:rest};return digit(9)===Number(d[9])&&digit(10)===Number(d[10])}
function validCnpj(value){const d=taxRaw(value);if(!/^[A-Z0-9]{12}\d{2}$/.test(d)||/^(\d)\1{13}$/.test(d))return false;const calculate=(base,weights)=>{const sum=[...base].reduce((total,char,index)=>total+(char.charCodeAt(0)-48)*weights[index],0),rest=sum%11;return rest<2?0:11-rest};const first=calculate(d.slice(0,12),[5,4,3,2,9,8,7,6,5,4,3,2]),second=calculate(d.slice(0,12)+first,[6,5,4,3,2,9,8,7,6,5,4,3,2]);return first===Number(d[12])&&second===Number(d[13])}
function validatePayload(p){
 if(p.type==='driver'&&p.cpf&&!validCpf(p.cpf))throw Error('Informe um CPF válido.');
 if(p.type==='company'&&p.document&&!validCnpj(p.document))throw Error('Informe um CNPJ válido, numérico ou alfanumérico.');
 if(p.type==='client'&&p.document){const raw=taxRaw(p.document),valid=raw.length===11&&!/[A-Z]/.test(raw)?validCpf(raw):validCnpj(raw);if(!valid)throw Error('Informe um CPF ou CNPJ válido.');}
 if(p.type==='vehicle'&&p.plate&&!/^[A-Z]{3}\d[A-Z0-9]\d{2}$/.test(taxRaw(p.plate)))throw Error('Informe uma placa brasileira válida, antiga ou Mercosul.');
 if(p.type==='trip'&&Number(p.kmEnd)<Number(p.kmStart))throw Error('O KM final não pode ser menor que o KM inicial.');
 if(p.type==='fuel'&&Number(p.liters)<=0)throw Error('Informe uma quantidade de litros maior que zero.');
 if(p.type==='financial'){if(p.status==='Pago'&&!p.paidDate)p.paidDate=today();if(p.status!=='Pago')p.paidDate='';}
 for(const key of ['phone','whatsapp'])if(p[key]){const size=String(p[key]).replace(/\D/g,'').length;if(![10,11,12,13].includes(size))throw Error('Informe telefone com DDD; para WhatsApp internacional, inclua o DDI.');}
 if(p.zipCode&&String(p.zipCode).replace(/\D/g,'').length!==8)throw Error('Informe um CEP com 8 dígitos.');
 if(p.channel==='whatsapp'&&p.recipient){const phone=String(p.recipient).replace(/\D/g,'');if(!/^55\d{10,11}$/.test(phone))throw Error('Para WhatsApp, informe +55, DDD e número.');}
 if(p.channel==='email'&&p.recipient&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.recipient))throw Error('Informe um e-mail válido para o destinatário.');
}
function downloadCsv(name,rows){const safe=value=>{let text=String(value??'');if(/^[=+\-@]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'},csv='\ufeff'+rows.map(row=>row.map(safe).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=name+'-'+today()+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportReport(kind){const d=state.data,financial=filterRows(d.financial);let rows=[];if(kind==='cashflow')rows=[['Mês','Entradas realizadas','Saídas realizadas','Entradas previstas','Saídas previstas','Saldo projetado'],...cashflowData(financial).map(x=>[monthLabel(x.key),x.inRealized,x.outRealized,x.inProjected,x.outProjected,x.inRealized+x.inProjected-x.outRealized-x.outProjected])];if(['receivable','payable','due'].includes(kind)){let list=financial.filter(x=>x.status!=='Pago'&&x.status!=='Cancelado');if(kind==='receivable')list=list.filter(x=>x.entry_type==='Receita');if(kind==='payable')list=list.filter(x=>x.entry_type==='Despesa');rows=[['Vencimento','Tipo','Descrição','Categoria','Veículo','Valor','Situação'],...list.map(x=>[x.due_date,x.entry_type,x.description,x.category,x.plate||'',financialValue(x),x.status])]}if(kind==='categories'){const map=new Map();financial.filter(x=>x.status!=='Cancelado').forEach(x=>{const row=map.get(x.category)||[x.category,0,0,0];if(x.entry_type==='Receita')row[1]+=financialValue(x);else row[2]+=financialValue(x);row[3]=row[1]-row[2];map.set(x.category,row)});rows=[['Categoria','Receitas','Despesas','Resultado'],...map.values()]}if(kind==='vehicles'){rows=[['Veículo','Receitas','Despesas','Resultado','Quilometragem']];for(const truck of d.trucks.filter(x=>state.filter==='todos'||x.id===state.filter)){const list=d.financial.filter(x=>x.truck_id===truck.id&&x.status!=='Cancelado'),revenue=list.filter(x=>x.entry_type==='Receita').reduce((s,x)=>s+financialValue(x),0),cost=list.filter(x=>x.entry_type==='Despesa').reduce((s,x)=>s+financialValue(x),0),km=d.trips.filter(x=>x.truck_id===truck.id).reduce((s,x)=>s+Math.max(0,Number(x.km_end)-Number(x.km_start)),0);rows.push([truck.plate,revenue,cost,revenue-cost,km])}}if(kind==='fuel')rows=[['Data','Veículo','Posto','Litros','Total','Preço por litro','Consumo'],...filterRows(d.fuel).map(x=>[x.fuel_date,x.plate,x.station,x.liters,x.total,x.price_per_liter,consumption(x)])];if(rows.length)downloadCsv('frota-facil-'+kind,rows)}
function applyMasks(){const mask=(input,format)=>{const update=()=>{input.value=format(input.value)};input.oninput=update;input.onblur=update;update()};$$('[data-mask="cpf"]').forEach(input=>mask(input,cpfMask));$$('[data-mask="cnpj"]').forEach(input=>mask(input,cnpjMask));$$('[data-mask="document"]').forEach(input=>mask(input,value=>{const raw=taxRaw(value);return raw.length<=11&&!/[A-Z]/.test(raw)?cpfMask(raw):cnpjMask(raw)}));$$('[data-mask="phone"]').forEach(input=>mask(input,value=>{let d=value.replace(/\D/g,'').slice(0,13),country='';if(d.startsWith('55')&&d.length>11){country='+55 ';d=d.slice(2)}if(d.length<=10)return country+d.replace(/(\d{2})(\d)/,'($1) $2').replace(/(\d{4})(\d)/,'$1-$2');return country+d.replace(/(\d{2})(\d)/,'($1) $2').replace(/(\d{5})(\d)/,'$1-$2')}));$$('[data-mask="cep"]').forEach(input=>mask(input,value=>value.replace(/\D/g,'').slice(0,8).replace(/(\d{5})(\d)/,'$1-$2')));$$('[data-mask="plate"]').forEach(input=>mask(input,value=>taxRaw(value).slice(0,7)));$$('[data-mask="digits"]').forEach(input=>mask(input,value=>value.replace(/\D/g,'').slice(0,Number(input.maxLength)||30)));$$('[data-mask="upper"]').forEach(input=>mask(input,value=>taxRaw(value).slice(0,Number(input.maxLength)||30)));$$('[data-mask="uf"]').forEach(input=>mask(input,value=>value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,2)))}
function openModal(type,id=''){state.type=type;state.editing=id||null;$('#fields').innerHTML=formFields(type);const names={trip:'viagem',vehicle:'veículo',driver:'motorista',client:'cliente',expense:'despesa',fuel:'abastecimento',maintenance:'serviço',document:'documento',financial:'lançamento financeiro',inspection:'checklist',occurrence:'ocorrência',rule:'regra automática',message:'mensagem',financialCategory:'categoria financeira',costCenter:'centro de custo',paymentMethod:'forma de pagamento',helper:'ajudante',telemetry:'posição',journey:'jornada',tire:'pneu',fine:'multa',inventory:'item de estoque'};$('#modalTitle').textContent=(id?'Editar ':'Novo ')+(names[type]||'registro');if(id){const record=(state.data[collections[type]]||[]).find(x=>String(x.id)===String(id));if(record)Array.from($('#entryForm').elements).forEach(input=>{if(!input.name)return;const value=recordValue(record,input.name,type);if(input.type==='checkbox')input.checked=value===true||Number(value)===1;else if(input.type!=='file'&&value!==undefined&&value!==null)input.value=value});if(['trip','expense','fuel','maintenance','document','fine'].includes(type)){const linked=(state.data.financial||[]).filter(x=>x.source_type===type&&String(x.source_id)===String(id)),assign=values=>values.forEach(([name,value])=>{const input=$('#entryForm [name="'+name+'"]');if(input&&value!==undefined&&value!==null)input.value=value});if(type==='trip'){const income=linked.find(x=>x.entry_type==='Receita'),expense=linked.find(x=>x.entry_type==='Despesa');if(income)assign([['incomeStatus',income.status],['incomeDueDate',income.due_date],['incomePaidDate',income.paid_date||''],['incomePaymentMethodId',income.payment_method_id||'']]);if(expense)assign([['expenseStatus',expense.status],['expenseDueDate',expense.due_date],['expensePaidDate',expense.paid_date||''],['expensePaymentMethodId',expense.payment_method_id||''],['costCenterId',expense.cost_center_id||'']])}else{const entry=linked[0];if(entry)assign([['financialStatus',entry.status],['dueDate',entry.due_date],['paidDate',entry.paid_date||''],['paymentMethodId',entry.payment_method_id||''],['costCenterId',entry.cost_center_id||'']])}}}$('#modal').classList.add('open');applyMasks();const attachment=$('#entryForm input[name="attachment"]');if(attachment)attachment.onchange=async()=>{try{const prepared=await prepareUpload(attachment.files[0],1600);if(!prepared)return;for(const [name,value] of [['attachmentName',prepared.name],['attachmentData',prepared.data]]){let hidden=$('#entryForm input[name="'+name+'"]');if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name=name;$('#entryForm').appendChild(hidden)}hidden.value=value}showError('')}catch(error){showError(error.message);attachment.value=''}}}
function bind(){$$('[data-new]').forEach(b=>b.onclick=()=>b.dataset.new&&openModal(b.dataset.new));$$('[data-edit]').forEach(b=>b.onclick=()=>openModal(b.dataset.edit,b.dataset.id));$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Deseja excluir este registro?'))return;try{await request('/api/data?type='+encodeURIComponent(b.dataset.delete)+'&id='+encodeURIComponent(b.dataset.id),{method:'DELETE'});await load()}catch(err){showError(err.message)}});$$('[data-settle]').forEach(b=>b.onclick=()=>{openModal('financial',b.dataset.settle);const status=$('#entryForm [name="status"]'),paid=$('#entryForm [name="paidDate"]');if(status)status.value='Pago';if(paid)paid.value=today()});$$('[data-finance-tab]').forEach(b=>b.onclick=()=>{state.financeTab=b.dataset.financeTab;render()});$$('[data-report-tab]').forEach(b=>b.onclick=()=>{state.reportTab=b.dataset.reportTab;render()});$$('[data-export]').forEach(b=>b.onclick=()=>exportReport(b.dataset.export));$$('[data-company-tab]').forEach(b=>b.onclick=()=>{state.companyTab=b.dataset.companyTab;render()});const logoInput=$('#companyLogo');if(logoInput)logoInput.onchange=async()=>{try{const prepared=await prepareUpload(logoInput.files[0],640);if(!prepared)return;$('#logoData').value=prepared.data;$('#logoPreview').innerHTML='<img src="'+prepared.data+'" alt="Prévia">';showError('')}catch(error){showError(error.message);logoInput.value=''}};const companyForm=$('#companyForm');if(companyForm)companyForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),body=Object.fromEntries(fd.entries());body.compactMode=fd.get('compactMode')==='on';delete body.companyLogo;try{validatePayload(body);await request('/api/data',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});await load()}catch(err){showError(err.message)}};const run=$('#runAutomations');if(run)run.onclick=async()=>{run.disabled=true;run.textContent='Executando...';try{const result=await request('/api/automations/run',{method:'POST'});await load();alert('Automação concluída: '+result.prepared+' aviso(s) preparado(s) e '+result.duplicates+' duplicado(s) ignorado(s).')}catch(err){showError(err.message)}finally{run.disabled=false;run.textContent='▶ Executar agora'}}}
async function request(url,options){showError('');const r=await fetch(url,options),d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível concluir.');return d}
const emojiPattern=/\p{Extended_Pictographic}/gu;
function removeEmojis(root=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const clean=node.nodeValue.replace(/🚚/gu,'FF').replace(emojiPattern,'');if(clean!==node.nodeValue)node.nodeValue=clean}}
const emojiObserver=new MutationObserver(records=>records.forEach(record=>{record.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE){const clean=node.nodeValue.replace(/🚚/gu,'FF').replace(emojiPattern,'');if(clean!==node.nodeValue)node.nodeValue=clean}else if(node.nodeType===Node.ELEMENT_NODE)removeEmojis(node)})}));
